                                                            folderVisualList.indexOfFirst {
                                                                it.id == targetId
                                                            }

                                                        if (
                                                            fromIndex >= 0 &&
                                                            targetIndex >= 0 &&
                                                            fromIndex != targetIndex
                                                        ) {
